// ---------------------- Highlighting engine ----------------------
// A Match represents a single highlight to apply: range [start,end) replaced with prefix+text+suffix
// where prefix is an ANSI escape sequence and suffix is the reset.
// For composite patterns, we can have multiple sub-matches within one overall match range.
type Match struct {
	start, end int
	pieces []Piece
	// priority: lower is higher priority (kept first)
	priority int
}
type Piece struct {
	start, end int
	ansi string // color code(s) like "36" or "3;34"
}

// Highlighter describes a way to search a line for matches.
type Highlighter interface {
	Name() string
	Find(line string) []Match
}

// Simple helpers for ANSI
func wrap(ansi, text string) string {
	if text == "" { return "" }
	return "\x1b[" + ansi + "m" + text + "\x1b[0m"
}

// applyMatches: takes a line and a list of matches. Sorts by priority then position.
// Non-overlapping matches with higher priority win. Returns final colored string.
func applyMatches(line string, matches []Match) string {
	// Sort by priority asc (higher priority first). Stable.
	sort.SliceStable(matches, func(i, j int) bool {
		if matches[i].priority != matches[j].priority {
			return matches[i].priority < matches[j].priority
		}
		return matches[i].start < matches[j].start
	})
	// Build a covered-mask and selected list
	covered := make([]bool, len(line))
	selected := []Match{}
	for _, m := range matches {
		overlaps := false
		for k := m.start; k < m.end; k++ {
			if k >= 0 && k < len(covered) && covered[k] {
				overlaps = true
				break
			}
		}
		if overlaps { continue }
		selected = append(selected, m)
		for k := m.start; k < m.end; k++ {
			if k >= 0 && k < len(covered) {
				covered[k] = true
			}
		}
	}
	// Now sort selected by start
	sort.SliceStable(selected, func(i, j int) bool { return selected[i].start < selected[j].start })
	var sb strings.Builder
	pos := 0
	for _, m := range selected {
		if m.start > pos {
			sb.WriteString(line[pos:m.start])
		}
		// Write pieces in order (they should be in order within the match)
		lastEnd := m.start
		for _, p := range m.pieces {
			if p.start > lastEnd {
				sb.WriteString(line[lastEnd:p.start])
			}
			sb.WriteString(wrap(p.ansi, line[p.start:p.end]))
			lastEnd = p.end
		}
		if lastEnd < m.end {
			sb.WriteString(line[lastEnd:m.end])
		}
		pos = m.end
	}
	if pos < len(line) {
		sb.WriteString(line[pos:])
	}
	return sb.String()
}

// ---------------------- Specific highlighters ----------------------

type regexMatcher struct {
	name string
	re *regexp.Regexp
	priority int
	// fn maps a regex match to a Match (with pieces)
	fn func(match []int, line string) Match
}
func (m *regexMatcher) Name() string { return m.name }
func (m *regexMatcher) Find(line string) []Match {
	out := []Match{}
	idxs := m.re.FindAllStringSubmatchIndex(line, -1)
	for _, ix := range idxs {
		mm := m.fn(ix, line)
		mm.priority = m.priority
		out = append(out, mm)
	}
	return out
}

func simple(ansi string, s, e int) Match {
	return Match{start:s, end:e, pieces:[]Piece{{s,e,ansi}}}
}

func buildHighlighters(c *Config) []Highlighter {
	hls := []Highlighter{}

	// Custom highlights (highest priority)
	// Actually custom highlights are applied too; priority?
	for _, h := range c.highlights {
		col := colorCode[h.color]
