			// group indices: pairs of (start,end)
			g := func(i int) (int,int) { return ix[2*i], ix[2*i+1] }
			pieces := []Piece{}
			add := func(s,e int, ansi string) {
				if s<0||e<0 { return }
				pieces = append(pieces, Piece{s,e,ansi})
			}
			s,e := g(1); add(s,e,"35")
			s,e = g(2); add(s,e,"2")
			s,e = g(3); add(s,e,"35")
			s,e = g(4); add(s,e,"2")
			s,e = g(5); add(s,e,"35")
			s,e = g(6); add(s,e,"31")
			s,e = g(7); add(s,e,"34")
			s,e = g(8); add(s,e,"2")
			s,e = g(9); add(s,e,"34")
			s,e = g(10); add(s,e,"2")
			s,e = g(11); add(s,e,"34")
			s,e = g(12); add(s,e,"2")
			s,e = g(13); add(s,e,"34")
			s,e = g(14); add(s,e,"31")
			return Match{start: ix[0], end: ix[1], pieces: pieces}
		}})
		// Standalone date YYYY-MM-DD or /
		reD := regexp.MustCompile(`(\d{4})([-/])(\d{2})([-/])(\d{2})`)
		hls = append(hls, &regexMatcher{name:"date", re:reD, priority: 11, fn: func(ix []int, line string) Match {
			g := func(i int) (int,int) { return ix[2*i], ix[2*i+1] }
			pieces := []Piece{}
			s,e := g(1); pieces = append(pieces, Piece{s,e,"35"})
			s,e = g(2); pieces = append(pieces, Piece{s,e,"2"})
			s,e = g(3); pieces = append(pieces, Piece{s,e,"35"})
			s,e = g(4); pieces = append(pieces, Piece{s,e,"2"})
			s,e = g(5); pieces = append(pieces, Piece{s,e,"35"})
			return Match{start: ix[0], end: ix[1], pieces: pieces}
		}})
		// Standalone time HH:MM:SS[.ms] or HH:MM:SS (must have at least :SS)
		reT := regexp.MustCompile(`\b(\d{2})(:)(\d{2})(:)(\d{2})(?:([.,:])(\d+))?\b`)
		hls = append(hls, &regexMatcher{name:"time", re:reT, priority: 12, fn: func(ix []int, line string) Match {
			g := func(i int) (int,int) { return ix[2*i], ix[2*i+1] }
			pieces := []Piece{}
			add := func(s,e int, ansi string) {
				if s<0||e<0 { return }
				pieces = append(pieces, Piece{s,e,ansi})
			}
			s,e := g(1); add(s,e,"34")
			s,e = g(2); add(s,e,"2")
			s,e = g(3); add(s,e,"34")
			s,e = g(4); add(s,e,"2")
			s,e = g(5); add(s,e,"34")
			s,e = g(6); add(s,e,"2")
			s,e = g(7); add(s,e,"34")
			return Match{start: ix[0], end: ix[1], pieces: pieces}
		}})
	}

	// URLs: http(s)://domain/path?query
	if isEnabled("urls") {
		re := regexp.MustCompile(`\b(https?)(://)([^\s/?]+)(/[^\s?]*)?(\?[^\s]*)?`)
		hls = append(hls, &regexMatcher{name:"url", re:re, priority: 14, fn: func(ix []int, line string) Match {
			g := func(i int) (int,int) {
				if 2*i+1 >= len(ix) { return -1,-1 }
				return ix[2*i], ix[2*i+1]
			}
			pieces := []Piece{}
			add := func(s,e int, ansi string) {
				if s<0||e<0 { return }
				pieces = append(pieces, Piece{s,e,ansi})
			}
			s,e := g(1)
			scheme := line[s:e]
			schemeColor := "2;31"
			if scheme == "https" { schemeColor = "2;32" }
			add(s,e,schemeColor)
			// :// group 2 - leave plain
			// domain
			s,e = g(3); add(s,e,"2;34")
			// path
			ps,pe := g(4)
			if ps>=0 { add(ps,pe,"34") }
			// query: break into ? key = value & key = value
			qs,qe := g(5)
			if qs>=0 && qe>qs {
				// emit query piece by piece
				q := line[qs:qe]
				pos := qs
				// First char is ?
				add(pos, pos+1, "31")
				pos++
				// parse key=value pairs separated by &
				for pos < qe {
					// find '=' or '&'
					i := pos
					for i < qe && q[i-qs] != '=' && q[i-qs] != '&' {
						i++
					}
					// key pos..i
					if i > pos { add(pos, i, "35") }
					if i < qe {
