							add(i, i+1, "31")
							pos = i+1
							// value until & or end
							j := pos
							for j < qe && q[j-qs] != '&' {
								j++
							}
							if j > pos { add(pos, j, "36") }
							pos = j
						} else if q[i-qs] == '&' {
							add(i, i+1, "31")
							pos = i+1
						}
					} else {
						pos = qe
					}
				}
			}
			return Match{start: ix[0], end: ix[1], pieces: pieces}
