		re := regexp.MustCompile(`(~/|/)([A-Za-z0-9._-]+(?:/[A-Za-z0-9._-]+)*)?/?`)
		_ = re
		re2 := regexp.MustCompile(`(?:~|/)(?:[A-Za-z0-9._-]+/)+[A-Za-z0-9._-]*|~/[A-Za-z0-9._-]*`)
		hls = append(hls, &regexMatcher{name:"path", re:re2, priority: 25, fn: func(ix []int, line string) Match {
			s,e := ix[0], ix[1]
			pieces := []Piece{}
			i := s
			for i < e {
				ch := line[i]
				if ch == '/' {
					pieces = append(pieces, Piece{i,i+1,"33"})
					i++
				} else if ch == '~' {
					pieces = append(pieces, Piece{i,i+1,"32"})
					i++
				} else {
