					j := i
					for j < e && line[j] != '/' {
						j++
					}
					pieces = append(pieces, Piece{i,j,"32"})
					i = j
				}
			}
			return Match{start:s, end:e, pieces: pieces}
		}})
	}

	// Processes: name[pid]:
	if isEnabled("processes") {
		re := regexp.MustCompile(`(\([\w/\-]+\)|[\w/\-]+)\[(\d+)\]:`)
		hls = append(hls, &regexMatcher{name:"process", re:re, priority: 30, fn: func(ix []int, line string) Match {
			// g1 yellow, [ red, g2 cyan, ] red
			pieces := []Piece{}
			gs, ge := ix[2], ix[3]
			pieces = append(pieces, Piece{gs, ge, "33"})
			// '['
			pieces = append(pieces, Piece{ge, ge+1, "31"})
			ps, pe := ix[4], ix[5]
			pieces = append(pieces, Piece{ps, pe, "36"})
			// ']'
			pieces = append(pieces, Piece{pe, pe+1, "31"})
			// ':' plain - leave as text
			// Match range excludes the colon so that it stays plain? Actually the full match includes :
			return Match{start: ix[0], end: ix[1]-1, pieces: pieces} // exclude trailing ':'
		}})
	}

	// Key-value pairs: (^|\s)key=
	if isEnabled("key-value-pairs") {
		re := regexp.MustCompile(`(^|\s)(\w+)(=)`)
		hls = append(hls, &regexMatcher{name:"kv", re:re, priority: 40, fn: func(ix []int, line string) Match {
			ks, ke := ix[4], ix[5]
			eq := ix[6]
			// Match range covers just key+= (not the leading space)
			pieces := []Piece{
				{ks, ke, "2"},
				{eq, eq+1, "37"},
			}
			return Match{start: ks, end: eq+1, pieces: pieces}
		}})
	}

	// Numbers
	if isEnabled("numbers") {
		re := regexp.MustCompile(`\b\d+(\.\d+)?\b`)
		hls = append(hls, &regexMatcher{name:"number", re:re, priority: 60, fn: func(ix []int, line string) Match {
			s,e := ix[0], ix[1]
			return simple("36", s, e)
		}})
	}

	// Quotes: `"..."`
	if isEnabled("quotes") {
		// "alone" on line (ignoring whitespace): dim quotes, plain content
		reAlone := regexp.MustCompile(`^\s*"([^"]*)"\s*$`)
		hls = append(hls, &quoteHL{reAlone: reAlone})
	}

	// Keyword highlighters (builtin keywords)
	if !c.disableBuiltin {
		// Severity
		sev := []struct{ re *regexp.Regexp; ansi string }{
			{regexp.MustCompile(`\bDEBUG\b`), "32"},
			{regexp.MustCompile(`\bINFO\b`), "37"},
			{regexp.MustCompile(`\bWARN\b`), "33"},
			{regexp.MustCompile(`\bERROR\b`), "31"},
			{regexp.MustCompile(`\bTRACE\b`), "2"},
		}
		for _, s := range sev {
			ansi := s.ansi
			hls = append(hls, &regexMatcher{name:"severity", re:s.re, priority: 5, fn: func(ix []int, line string) Match {
				return simple(ansi, ix[0], ix[1])
			}})
		}
		// Booleans/null
		reBool := regexp.MustCompile(`\b(?:true|false|null)\b`)
		hls = append(hls, &regexMatcher{name:"bool", re: reBool, priority: 5, fn: func(ix []int, line string) Match {
			return simple("3;31", ix[0], ix[1])
		}})
		// REST verbs - they wrap with spaces
		reRest := regexp.MustCompile(`\b(GET|POST|PUT|DELETE|PATCH)\b`)
		hls = append(hls, &restMatcher{re: reRest})
	}

	return hls
}

type quoteHL struct { reAlone *regexp.Regexp }
func (q *quoteHL) Name() string { return "quotes" }
func (q *quoteHL) Find(line string) []Match {
	out := []Match{}
	if ix := q.reAlone.FindStringSubmatchIndex(line); ix != nil {
		// wrap quotes in dim
		ms, me := ix[2]-1, ix[3]+1 // positions of the quotes (opening, closing)
		if me <= len(line) && ms >= 0 {
			pieces := []Piece{
				{ms, ms+1, "2"},
				{me-1, me, "2"},
			}
			out = append(out, Match{start: ms, end: me, pieces: pieces, priority: 50})
		}
		return out
	}
	// Otherwise: wrap whole quoted strings in yellow
	reAll := regexp.MustCompile(`"[^"\n]*"`)
	for _, m := range reAll.FindAllStringIndex(line, -1) {
		s, e := m[0], m[1]
		out = append(out, Match{start: s, end: e, pieces: []Piece{{s, e, "33"}}, priority: 50})
	}
	return out
}

type restMatcher struct { re *regexp.Regexp }
func (r *restMatcher) Name() string { return "rest" }
func (r *restMatcher) Find(line string) []Match {
	out := []Match{}
	for _, m := range r.re.FindAllStringIndex(line, -1) {
		s, e := m[0], m[1]
		verb := line[s:e]
		bg := "42"
		switch verb {
		case "GET": bg = "42"
		case "POST": bg = "43"
		case "PUT", "PATCH": bg = "45"
		case "DELETE": bg = "41"
		}
		// pieces: we want to REPLACE the matched text with ` VERB ` wrapped.
		// Since our framework replaces text[start:end] with prefix+line[start:end]+suffix,
		// we need a piece where the "text" is ` VERB ` not just VERB. But our current
		// engine only inserts ANSI around line[s:e]. Workaround: we handle this differently.
		// For now, treat as whole match wrapped with ansi `bg;30`, text from match+padding via a custom path.
		_ = bg
		// Hack: produce a special piece that has synthetic start/end and stores info
		// Instead we'll signal via ansi = "bg;30;@rest" - but ansi is used to wrap line[start:end].
		// Alternative: extend Match to have pre/post text.
		pieces := []Piece{{s, e, "SP_REST_" + bg}}
		out = append(out, Match{start: s, end: e, pieces: pieces, priority: 5})
	}
	return out
}

// processLine
func processLine(line string, hls []Highlighter) string {
	all := []Match{}
	for _, h := range hls {
		all = append(all, h.Find(line)...)
	}
	return applyMatchesV2(line, all)
}

// applyMatchesV2: supports special REST rendering
func applyMatchesV2(line string, matches []Match) string {
	sort.SliceStable(matches, func(i, j int) bool {
		if matches[i].priority != matches[j].priority {
			return matches[i].priority < matches[j].priority
		}
		return matches[i].start < matches[j].start
	})
	covered := make([]bool, len(line))
	selected := []Match{}
	for _, m := range matches {
		overlaps := false
		for k := m.start; k < m.end; k++ {
			if k >= 0 && k < len(covered) && covered[k] {
				overlaps = true
				break
			}
		}
		if overlaps { continue }
		selected = append(selected, m)
		for k := m.start; k < m.end; k++ {
			if k >= 0 && k < len(covered) {
				covered[k] = true
			}
		}
	}
	sort.SliceStable(selected, func(i, j int) bool { return selected[i].start < selected[j].start })
	var sb strings.Builder
	pos := 0
	for _, m := range selected {
		if m.start > pos {
			sb.WriteString(line[pos:m.start])
		}
		lastEnd := m.start
		for _, p := range m.pieces {
			if p.start > lastEnd {
				sb.WriteString(line[lastEnd:p.start])
			}
			if strings.HasPrefix(p.ansi, "SP_REST_") {
				bg := strings.TrimPrefix(p.ansi, "SP_REST_")
				sb.WriteString("\x1b[" + bg + ";30m " + line[p.start:p.end] + " \x1b[0m")
			} else {
				sb.WriteString(wrap(p.ansi, line[p.start:p.end]))
			}
			lastEnd = p.end
		}
		if lastEnd < m.end {
			sb.WriteString(line[lastEnd:m.end])
		}
		pos = m.end
	}
	if pos < len(line) {
		sb.WriteString(line[pos:])
	}
	return sb.String()
}

func main() {
	c, err := parseArgs(os.Args[1:])
	if err != nil {
		fmt.Fprint(os.Stderr, err.Error())
		os.Exit(2)
	}

	// Determine input
	var r io.Reader
	if c.file != "" {
		f, err := os.Open(c.file)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error:   \u26a0  \x1b[33m%s\x1b[0m: No such file or directory\n\n", c.file)
			return
		}
		defer f.Close()
		r = f
	} else {
		r = os.Stdin
	}

	hls := buildHighlighters(c)
	br := bufio.NewReader(r)
	bw := bufio.NewWriter(os.Stdout)
	defer bw.Flush()
	for {
		line, err := br.ReadString('\n')
		if len(line) > 0 {
			hadNL := strings.HasSuffix(line, "\n")
			if hadNL {
				line = line[:len(line)-1]
			}
			out := processLine(line, hls)
			bw.WriteString(out)
			if hadNL {
				bw.WriteByte('\n')
			}
		}
		if err != nil { break }
	}
}
