// ---------------------- Highlighting engine ----------------------
type Match struct {
	start, end int
	pieces     []Piece
	priority   int
	// optional replacement text (if set, replaces line[start:end] entirely for rendering)
	replace string
}
type Piece struct {
	start, end int
	ansi       string
}

type Highlighter interface {
	Name() string
	Find(line string) []Match
}

func wrap(ansi, text string) string {
	return "\x1b[" + ansi + "m" + text + "\x1b[0m"
}

func applyMatches(line string, matches []Match) string {
	sort.SliceStable(matches, func(i, j int) bool {
		if matches[i].priority != matches[j].priority {
			return matches[i].priority < matches[j].priority
		}
		return matches[i].start < matches[j].start
	})
	covered := make([]bool, len(line))
	selected := []Match{}
	for _, m := range matches {
		overlaps := false
		for k := m.start; k < m.end; k++ {
			if k >= 0 && k < len(covered) && covered[k] {
				overlaps = true
				break
			}
		}
		if overlaps {
			continue
		}
		selected = append(selected, m)
		for k := m.start; k < m.end; k++ {
			if k >= 0 && k < len(covered) {
				covered[k] = true
			}
		}
	}
	sort.SliceStable(selected, func(i, j int) bool { return selected[i].start < selected[j].start })
	var sb strings.Builder
	pos := 0
	for _, m := range selected {
		if m.start > pos {
			sb.WriteString(line[pos:m.start])
		}
		if m.replace != "" {
			sb.WriteString(m.replace)
		} else {
			lastEnd := m.start
			for _, p := range m.pieces {
				if p.start > lastEnd {
					sb.WriteString(line[lastEnd:p.start])
				}
				sb.WriteString(wrap(p.ansi, line[p.start:p.end]))
				lastEnd = p.end
			}
			if lastEnd < m.end {
				sb.WriteString(line[lastEnd:m.end])
			}
		}
		pos = m.end
	}
	if pos < len(line) {
		sb.WriteString(line[pos:])
	}
	return sb.String()
}

type regexMatcher struct {
	name     string
	re       *regexp.Regexp
	priority int
	fn       func(match []int, line string) Match
}

func (m *regexMatcher) Name() string { return m.name }
func (m *regexMatcher) Find(line string) []Match {
	out := []Match{}
	idxs := m.re.FindAllStringSubmatchIndex(line, -1)
	for _, ix := range idxs {
		mm := m.fn(ix, line)
		mm.priority = m.priority
		out = append(out, mm)
	}
	return out
}

func simple(ansi string, s, e int) Match {
	return Match{start: s, end: e, pieces: []Piece{{s, e, ansi}}}
}

// Priority scheme: lower = higher priority
// 0-9: custom highlights and highest-priority structured patterns
// 10-19: URLs, processes
// 20-29: UUIDs, date/time, IPs, pointers
// 30-39: paths
// 40-49: quotes, kv
// 50-59: REST verbs
// 60-69: severity
// 70-79: booleans/nulls
// 80-89: numbers

func buildHighlighters(c *Config) []Highlighter {
	hls := []Highlighter{}

	for _, h := range c.highlights {
		col := colorCode[h.color]
		var words []string
		for _, w := range h.words {
			if w == "" {
				continue
			}
			words = append(words, regexp.QuoteMeta(w))
		}
		if len(words) == 0 {
			continue
		}
		re := regexp.MustCompile(`\b(?:` + strings.Join(words, "|") + `)\b`)
		ansi := col
		hls = append(hls, &regexMatcher{name: "custom", re: re, priority: 0, fn: func(ix []int, line string) Match {
			s, e := ix[0], ix[1]
			return simple(ansi, s, e)
		}})
	}

	isEnabled := func(name string) bool {
		if len(c.enabled) > 0 {
			return c.enabled[name]
		}
		if c.disabled[name] {
			return false
		}
		return true
	}

	// URLs: http(s)://domain/path?query
	if isEnabled("urls") {
		re := regexp.MustCompile(`\b(https?)(://)([^\s/?]+)(/[^\s?]*)?(\?[^\s]*)?`)
		hls = append(hls, &regexMatcher{name: "url", re: re, priority: 10, fn: func(ix []int, line string) Match {
			g := func(i int) (int, int) {
				if 2*i+1 >= len(ix) {
					return -1, -1
				}
				return ix[2*i], ix[2*i+1]
			}
			pieces := []Piece{}
			add := func(s, e int, ansi string) {
				if s < 0 || e < 0 {
					return
				}
				pieces = append(pieces, Piece{s, e, ansi})
			}
			s, e := g(1)
			scheme := line[s:e]
			schemeColor := "2;31"
			if scheme == "https" {
				schemeColor = "2;32"
			}
			add(s, e, schemeColor)
			s, e = g(3)
			add(s, e, "2;34")
			ps, pe := g(4)
			if ps >= 0 {
				add(ps, pe, "34")
			}
			qs, qe := g(5)
			if qs >= 0 && qe > qs {
				q := line[qs:qe]
				pos := qs
				add(pos, pos+1, "31")
				pos++
				for pos < qe {
					i := pos
					for i < qe && q[i-qs] != '=' && q[i-qs] != '&' {
						i++
					}
					if i > pos {
						add(pos, i, "35")
					}
					if i < qe {
						if q[i-qs] == '=' {
							add(i, i+1, "31")
							pos = i + 1
							j := pos
							for j < qe && q[j-qs] != '&' {
								j++
							}
							if j > pos {
								add(pos, j, "36")
							}
							pos = j
						} else if q[i-qs] == '&' {
							add(i, i+1, "31")
							pos = i + 1
						}
					} else {
						pos = qe
					}
				}
			}
			return Match{start: ix[0], end: ix[1], pieces: pieces}
		}})
	}

