	if isEnabled("processes") {
		re := regexp.MustCompile(`(\([\w/\-]+\)|[\w/\-]+)\[(\d+)\]:`)
		hls = append(hls, &regexMatcher{name: "process", re: re, priority: 12, fn: func(ix []int, line string) Match {
			pieces := []Piece{}
			gs, ge := ix[2], ix[3]
			pieces = append(pieces, Piece{gs, ge, "33"})
			pieces = append(pieces, Piece{ge, ge + 1, "31"})
			ps, pe := ix[4], ix[5]
			pieces = append(pieces, Piece{ps, pe, "36"})
			pieces = append(pieces, Piece{pe, pe + 1, "31"})
