	// UUID
	if isEnabled("uuids") {
		re := regexp.MustCompile(`\b[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}\b`)
		hls = append(hls, &regexMatcher{name: "uuid", re: re, priority: 15, fn: func(ix []int, line string) Match {
			pieces := []Piece{}
			s, e := ix[0], ix[1]
			for i := s; i < e; i++ {
