	if isEnabled("pointers") {
		re := regexp.MustCompile(`\b0x[0-9a-fA-F]+\b`)
		hls = append(hls, &regexMatcher{name: "pointer", re: re, priority: 26, fn: func(ix []int, line string) Match {
			pieces := []Piece{}
			s, e := ix[0], ix[1]
			pieces = append(pieces, Piece{s, s + 1, "3;34"})
			pieces = append(pieces, Piece{s + 1, s + 2, "31"})
			for i := s + 2; i < e; i++ {
				ch := line[i]
				var ansi string
				if ch >= '0' && ch <= '9' {
					ansi = "3;34"
				} else {
					ansi = "3;35"
				}
				pieces = append(pieces, Piece{i, i + 1, ansi})
