	if isEnabled("paths") {
		re := regexp.MustCompile(`(?:~|/)(?:[A-Za-z0-9._-]+/)+[A-Za-z0-9._-]*|~/[A-Za-z0-9._-]*`)
		hls = append(hls, &regexMatcher{name: "path", re: re, priority: 30, fn: func(ix []int, line string) Match {
			s, e := ix[0], ix[1]
			pieces := []Piece{}
			i := s
			for i < e {
				ch := line[i]
				if ch == '/' {
					pieces = append(pieces, Piece{i, i + 1, "33"})
					i++
				} else if ch == '~' {
					pieces = append(pieces, Piece{i, i + 1, "32"})
					i++
				} else {
					j := i
					for j < e && line[j] != '/' {
						j++
					}
					pieces = append(pieces, Piece{i, j, "32"})
					i = j
				}
			}
			return Match{start: s, end: e, pieces: pieces}
		}})
	}

	// Quotes
	if isEnabled("quotes") {
		reAlone := regexp.MustCompile(`^\s*"([^"]*)"\s*$`)
