	if isEnabled("key-value-pairs") {
		re := regexp.MustCompile(`(^|\s)(\w+)(=)`)
		hls = append(hls, &regexMatcher{name: "kv", re: re, priority: 45, fn: func(ix []int, line string) Match {
			ks, ke := ix[4], ix[5]
			eq := ix[6]
			pieces := []Piece{
				{ks, ke, "2"},
				{eq, eq + 1, "37"},
			}
			return Match{start: ks, end: eq + 1, pieces: pieces}
		}})
