	words []string
}

var validHighlighters = []string{"numbers", "urls", "pointers", "dates", "paths", "quotes", "key-value-pairs", "uuids", "ip-addresses", "processes", "json"}
var validColors = []string{"red", "green", "yellow", "blue", "magenta", "cyan"}
var colorCode = map[string]string{
	"red": "31", "green": "32", "yellow": "33", "blue": "34", "magenta": "35", "cyan": "36",
}

