json_hl = '''
type jsonHL struct{}

func (h *jsonHL) Name() string { return "json" }
func (h *jsonHL) Find(line string) []Match {
	// Detect JSON-line: starts with { (after whitespace), ends with }
	s := strings.TrimSpace(line)
	if len(s) == 0 || s[0] != '{' || s[len(s)-1] != '}' {
		return nil
	}
	// Find real start/end in line
	start := strings.IndexByte(line, '{')
	end := strings.LastIndexByte(line, '}')
	if start < 0 || end <= start {
		return nil
	}
	// Tokenize and build a replacement string
	var sb strings.Builder
	sb.WriteString(wrap("2", "{"))
	sb.WriteString(" ")
	i := start + 1
	for i <= end {
		ch := line[i]
		// Skip whitespace
		if ch == ' ' || ch == '\\t' {
			sb.WriteByte(ch)
			i++
			continue
		}
		if ch == '}' {
			sb.WriteString(" ")
			sb.WriteString(wrap("2", "}"))
			i++
			continue
		}
		if ch == ',' {
			sb.WriteString(wrap("2", ","))
			i++
			continue
		}
		if ch == ':' {
			sb.WriteString(wrap("2", ":"))
			i++
			continue
		}
		if ch == '"' {
			// Find matching end quote
			j := i + 1
			for j <= end && line[j] != '"' {
				if line[j] == '\\\\' && j+1 <= end {
					j += 2
					continue
				}
				j++
			}
			if j > end {
				// No closing quote, emit rest as-is
				sb.WriteString(line[i:])
				break
			}
			// Determine if this is a key (followed by :) or a value
			k := j + 1
			for k <= end && (line[k] == ' ' || line[k] == '\\t') {
				k++
			}
			isKey := k <= end && line[k] == ':'
			sb.WriteString(wrap("2", "\\""))
			if isKey {
				sb.WriteString(wrap("2", line[i+1:j]))
			} else {
				// Apply other highlighters to content
				sub := line[i+1 : j]
				// Recursively run highlighters (just run processLine with a specific set? simpler: call a helper that uses the global highlighters list minus json)
				sb.WriteString(subHighlight(sub))
			}
			sb.WriteString(wrap("2", "\\""))
			i = j + 1
			continue
		}
		// Number, true/false/null, or other
		// Use a simple scan until next structural char
		j := i
		for j <= end && line[j] != ',' && line[j] != '}' && line[j] != ':' && line[j] != '"' && line[j] != ' ' && line[j] != '\\t' {
			j++
		}
		sub := line[i:j]
		sb.WriteString(subHighlight(sub))
		i = j
	}
	return []Match{{start: start, end: end + 1, replace: sb.String(), priority: 3}}
}

// Variable holding the other highlighters for sub-highlighting JSON values.
var subHighlighters []Highlighter

func subHighlight(s string) string {
	if len(subHighlighters) == 0 {
		return s
	}
	all := []Match{}
	for _, h := range subHighlighters {
		all = append(all, h.Find(s)...)
	}
	return applyMatches(s, all)
}
'''
c = c.replace('type jsonHL struct{}', 'type _placeholder_jsonHL struct{}') if 'type jsonHL struct{}' in c else c
c = c.replace('type pathHL struct{}', json_hl + '\ntype pathHL struct{}')

